eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   defaultConfig: () => (/* binding */ defaultConfig)\n/* harmony export */ });\n// Default configuration for the wedding website\n// This can be edited via the admin dashboard\nconst defaultConfig = {\n    \"hero\": {\n        \"date\": \"22. August 2026\",\n        \"name1\": \"Petra\",\n        \"name2\": \"Michi\",\n        \"title\": \"Wir trauen uns!\",\n        \"fontSize\": {\n            \"date\": \"text-2xl\",\n            \"names\": \"text-6xl\",\n            \"title\": \"text-3xl\"\n        },\n        \"backgroundImage\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.39.jpeg\"\n    },\n    \"countdown\": {\n        \"title\": \"Der große Tag kommt näher\",\n        \"fontSize\": {\n            \"title\": \"text-4xl\",\n            \"subtitle\": \"text-lg\"\n        },\n        \"subtitle\": \"Wir können es kaum erwarten, mit euch zu feiern!\",\n        \"weddingDate\": \"2026-08-22T11:00:00\"\n    },\n    \"details\": {\n        \"events\": [\n            {\n                \"icon\": \"📍\",\n                \"time\": \"10:30 Uhr\",\n                \"title\": \"ES GEHT LOS!\",\n                \"address\": \"\",\n                \"location\": \"Dorfplatz Terlan\",\n                \"description\": \"Liebe Gäste, bitte findet euch um 10:30 Uhr beim Dorfplatz vor der Pfarrkirche Mariä Himmelfahrt in Terlan ein. Ankunft der Braut geplant für...ja, wenn Petra dann halt soweit ist.😉 \\n\\nOje, ihr Weg führt direkt am Wieterer vorbei, d.h. es kann - sagen wir mal - sich etwas verzögern..., aber für einen letzten Monte al volo als unverheiratete Frau muss auf jeden Fall Zeit sein ;) \"\n            },\n            {\n                \"icon\": \"💍\",\n                \"time\": \"11:00 Uhr\",\n                \"title\": \"VON HIER BIS UNENDLICH \",\n                \"address\": \"Kirchliche Trauung\",\n                \"location\": \"Pfarrkirche Mariä Himmelfahrt, Terlan\",\n                \"description\": \"Michi hat sich nach dem 'First Look' wieder ein wenig gesammelt und zieht nun gemeinsam mit den Gästen feierlich in die Kirche ein – ein aufregender Moment zwischen Vorfreude und Herzklopfen. \\n\\nPetra wird ganz nach ihrem Herzenswunsch von ihrem Tata in die Kirche geführt. Ein berührender Augenblick voller Stolz & Verbundenheit, der mehr als 1000 Worte. \\n\\nBlumenkinder bereiten den Weg mit zarten Blüten für das, was nun beginnt: ein gemeinsames Kapitel voller Glück! \\n\\nLiebe Gäste, um diese unvergesslichen Augenblicke ganz bewusst und ungestört genießen zu können, wird ein Fotograf alle Emotionen festhalten. Eure Handys und Kameras dürfen getrost in der Tasche bleiben, sodass eure Hände frei sind – sei es für ein Taschentuch 😉 oder um nach dem First Kiss zu applaudieren.\"\n            },\n            {\n                \"icon\": \"❤️\",\n                \"time\": \"12.30\",\n                \"title\": \"ZOMM - ZOMM - ZOMM.....PROOOOOOST!\",\n                \"address\": \"\",\n                \"location\": \"Café Wieteter\",\n                \"description\": \"Liebe Gäste, nach der Trauung verlieren wir keine Zeit und spazieren gemeinsam zum Cafè Wieterer. Dort warten Weißwurst, Fingerfood und ausreichend Flüssiges, um auf die Liebe und auf das junge Brautpaar anzustoßen, das gemeinsam beschlossen hat, den Rest des Lebens ZOMM - ZOMM - ZOMM ... zu verbringen!\\n\"\n            },\n            {\n                \"icon\": \"🎉\",\n                \"time\": \"16:00 Uhr\",\n                \"title\": \"Schloss Katzenzungen\",\n                \"address\": \"\",\n                \"location\": \"39010 Prissian\",\n                \"description\": \"Die erste Ausfahrt als verheiratetes Paar dürfen die beiden ganz alleine genießen und den Moment nutzen, um kurz zu verschnaufen. Sich bewusst werden: aus Liebe machen manche Leute ja sehr verrückte Dinge - einige heiraten sogar!\\n\\nDie 30 hupenden Autos im Konvoi auf den Weg zum Schloss Katzenzungen können Sie ja versuchen zu ignorieren! Dort angekommen, werden die Gäste mit einem \\\"herzlichen Willkommen zu unserem Für-Immer\\\" empfangen und zur Abwechslung gibt es mal was zu trinken!\\n\\nDas Schloss bietet die perfekte Kulisse für traumhafte Fotos. Das Brautpaar ist nun eine Weile beschäftigt, aber die coolen Jungs der Band Jam'son sorgen dafür, dass die Stimmung passt. À propos Jungs:. Luis und seine Buabn verwöhnen die Gäste mit kulinarischen Köstlichkeiten und der erste Gang lässt nicht lange auf sich warten. Zum Hauptgang finden wir uns im Schloss-Saal ein. An dieser Stelle noch die Bitte, etwaige Allergien und Unverträglichkeiten bitte bis 1. August mitzuteilen. Alle Gäste sollen kulinarisch verzaubert werden in diesem märchenhaften Ambiente!\\n\\nFür alle ohne Allergien: gegessen wird was auf den Tisch kommt! Wem es nicht schmeckt, der muss halt trinken was er Hunger hat.\\n\\nNach dem großen Auftritt der Küchencrew, folgt der große Auftritt des Brautpaares: der erste Tanz als verheiratetes Paar! Die Tanzfläche wird eröffnet und ab geht die Party - die Party geht ab....!\\n\\nAbgelöst werden die Jam'son zu späterer Stunde von DJ Lagxury. Wie, noch nie gehört? Gehört zu den Top-DJ's vom Wörthersee.\\n\\nUnd wer bei \\\"volare\\\" meint, sitzen zu müssen, dem wird mit einem Monte al volo geholfen!\"\n            }\n        ],\n        \"fontSize\": {\n            \"eventTime\": \"text-lg\",\n            \"introText\": \"text-lg\",\n            \"eventTitle\": \"text-2xl\",\n            \"footerText\": \"text-lg\",\n            \"introTitle\": \"text-2xl\",\n            \"eventDescription\": \"text-lg\"\n        },\n        \"introText\": \"Wir können es kaum erwarten, diesen besonderen Tag mit euch zu verbringen! \\nHier bekommt ihr schon mal einen kleinen Vorgeschmack darauf, wie wir uns das große Spektakel vorstellen -\\nAchtung Spoiler: Es wird wunderbar, vielleicht ein bisschen verrückt und auf jeden Fall unvergesslich! \",\n        \"footerText\": \"💍 Wir freuen uns auf euch! 💍\",\n        \"introTitle\": \"Wir trauen uns - jetzt passiert's,\\nam 22. August 2026 eskaliert's (sowieso)\\nWir laden euch ganz herzlich ein,\\nVollgas dabei zu sein! 🎉🥳🥂\\n\"\n    },\n    \"gallery\": {\n        \"title\": \"Unsere Galerie\",\n        \"images\": [\n            {\n                \"id\": 1,\n                \"alt\": \"Thailand Abenteuer\",\n                \"src\": \"/imagespetramichi/3db1c6f8-16dd-4cab-adc2-a58ed1e4af98.jpg\"\n            },\n            {\n                \"id\": 2,\n                \"alt\": \"Der Verlobungsring\",\n                \"src\": \"/imagespetramichi/7a497409-53ec-44cc-af0b-43cdc7b02983.jpg\"\n            },\n            {\n                \"id\": 3,\n                \"alt\": \"Kuss auf dem Boot\",\n                \"src\": \"/imagespetramichi/36b3d9dc-583d-4697-9947-e7bfb09d4987.jpg\"\n            },\n            {\n                \"id\": 4,\n                \"alt\": \"Sommerliebe am Meer\",\n                \"src\": \"/imagespetramichi/37c75c7f-a09e-4655-8183-5ab5bafc7d4f.jpg\"\n            },\n            {\n                \"id\": 5,\n                \"alt\": \"Strandmomente\",\n                \"src\": \"/imagespetramichi/95e59027-c985-4152-9fb5-c8bb5a5bf44e.jpg\"\n            },\n            {\n                \"id\": 6,\n                \"alt\": \"Städtetrip\",\n                \"src\": \"/imagespetramichi/56970c7c-0bd9-470f-849e-e49dff77b954.jpg\"\n            },\n            {\n                \"id\": 7,\n                \"alt\": \"Glückliche Gesichter\",\n                \"src\": \"/imagespetramichi/93800d24-1569-45dc-b022-b3b5be00368a.jpg\"\n            },\n            {\n                \"id\": 8,\n                \"alt\": \"Partyzeit\",\n                \"src\": \"/imagespetramichi/abd1a336-f183-44d4-8610-c4153ef60cfc.jpg\"\n            },\n            {\n                \"id\": 9,\n                \"alt\": \"Sonnenuntergang\",\n                \"src\": \"/imagespetramichi/c1aed810-2001-443a-b365-eef9f5d4f8ba.jpg\"\n            },\n            {\n                \"id\": 10,\n                \"alt\": \"Karneval / Batman & Catwoman\",\n                \"src\": \"/imagespetramichi/c56d6849-49ee-416d-8ca4-4ed0040a9740.jpg\"\n            },\n            {\n                \"id\": 11,\n                \"alt\": \"Ausflug\",\n                \"src\": \"/imagespetramichi/fa9a9dfa-0d95-4073-bcf5-dfc2a67aefd4.jpg\"\n            },\n            {\n                \"id\": 12,\n                \"alt\": \"Urlaubsmomente\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.38.jpeg\"\n            },\n            {\n                \"id\": 13,\n                \"alt\": \"Sonnenuntergang am Strand\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.39.jpeg\"\n            },\n            {\n                \"id\": 14,\n                \"alt\": \"Familienglück am Meer\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.40.jpeg\"\n            },\n            {\n                \"id\": 15,\n                \"alt\": \"Weihnachtszeit\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.41.jpeg\"\n            },\n            {\n                \"id\": 16,\n                \"alt\": \"Aperitif am See\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.42.jpeg\"\n            },\n            {\n                \"id\": 17,\n                \"alt\": \"Lachen in der Sonne\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.43.jpeg\"\n            },\n            {\n                \"id\": 18,\n                \"alt\": \"Ein Kuss zwischendurch\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.44.jpeg\"\n            },\n            {\n                \"id\": 19,\n                \"alt\": \"Konzertbesuch\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.45.jpeg\"\n            },\n            {\n                \"id\": 20,\n                \"alt\": \"Ein Prosit\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.46.jpeg\"\n            },\n            {\n                \"id\": 21,\n                \"alt\": \"Schick gemacht\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.47.jpeg\"\n            },\n            {\n                \"id\": 22,\n                \"alt\": \"Auf dem Boot\",\n                \"src\": \"/imagespetramichi/WhatsApp Image 2026-02-20 at 13.11.48.jpeg\"\n            }\n        ],\n        \"fontSize\": {\n            \"title\": \"text-4xl\",\n            \"subtitle\": \"text-lg\",\n            \"footerText\": \"text-2xl\"\n        },\n        \"subtitle\": \"Momente, die wir für immer in unseren Herzen tragen\",\n        \"footerText\": \"\"\n    },\n    \"footer\": {\n        \"names\": \"Petra & Michi\",\n        \"subText\": \"...und auf's Feiern\",\n        \"fontSize\": {\n            \"names\": \"text-4xl\",\n            \"subText\": \"text-sm\",\n            \"mainText\": \"text-lg\",\n            \"copyright\": \"text-xs\"\n        },\n        \"mainText\": \"Wir freuen uns auf diesen besonderen Tag mit euch!\",\n        \"copyright\": \"© 2026 Petra & Michi. Alle Rechte vorbehalten.\"\n    },\n    \"story\": {\n        \"title\": \"Unsere Story\",\n        \"subtitle\": \"oder besser gesagt: Sie kam - er sah - sie siegte! \",\n        \"introText\": \"Wir machen uns nichts vor: Der Anfang dieser Geschichte war vielleicht nicht ganz wie im Märchenbuch. Vor knapp 20 Jahren war Petra in Michis damaligem Lokal „Treffpunkt\\\" öfter zu Gast. Doch Damen, die rauchen, waren für ihn schon immer ein No-Go – und für Petra entsprach der „Schnösel\\\" Michi so gar nicht ihrem Beuteschema. Liebe auf den ersten Blick? Eher nicht.\\n\\nAls Michi vor rund 4 Jahren im Algo Petra auf der Rolltreppe wiederentdeckte, war sein erster Gedanke – nun ja, sagen wir es dezent – nicht unbedingt Gentleman-like. Aber sind wir ehrlich: Bei Petra kann man schon mal den Kopf verlieren!\\n\\nWie praktisch, dass Petra mittlerweile bei Athesia, gleich gegenüber vom Come In, arbeitete. Und ganz nebenbei hatte sie in den letzten Jahren die Zigaretten gegen ihre kleine Sophia eingetauscht.\\n\\nNach wenigen Wochen – und einigen „zufälligen\\\" Treffen bei den Kartonmülltonnen (in dieser Zeit wurde wohl jedes Fitzelchen Papier von den beiden einzeln entsorgt) – war klar: Das war mehr als nur ein Flirt. Es begann eine aufregende Zeit voller Leichtigkeit, Spontaneität und diesem besonderen Gefühl, einfach lebendig zu sein, ohne viel Schlaf zu brauchen. Spontane Motorradausflüge zum Gardasee, den Alltag auch mal ausblenden und stattdessen einfach den Moment genießen.\\n\\nPetra hatte weiß Gott keine einfache Zeit hinter sich. Umso schöner war es, zu sehen, wie sie Schritt für Schritt wieder aufblühte.\\n\\nUnd Michi? Der redete sich anfangs noch ein, man könne das Ganze ja langsam angehen. Ganz sicher würde er sich diesmal nicht Hals über Kopf in die nächste Beziehung stürzen… Aber soll man sich wirklich gegen etwas wehren, das sich so verdammt richtig anfühlt?\\n\\nUnd als Michi schließlich Sophia kennenlernen durfte, wurde alles nur noch eindeutiger: Nicht nur Petra hatte ihm den Kopf verdreht – die kleine Maus hatte sein Herz im Sturm erobert. Spätestens als Sami irgendwann sagte: „So glücklich habe ich den Papi noch nie erlebt\\\", war klar, wohin die Reise geht. Und so öffnete Michi nicht nur sein Herz, sondern auch seine Haustür ganz weit – und Petra nistete sich nach und nach in Obermais ein.\\n\\nJa, apropos „einnisten\\\" …\\n\\nMachen wir einen kleinen Sprung zum Dezember 2022. Man spricht über dies und das, auch über Zukunftspläne. Auf die konkrete Frage, ob sich Michi noch Kinder wünsche, lautete seine Antwort damals ganz klar: „Naja, jetzt sofort sicher nicht. Schauen wir mal …\\\" Nein, natürlich nicht sofort, denn so eine Schwangerschaft dauert ja Gott sei Dank 9 Monate. Denn was sie zu diesem Zeitpunkt noch nicht wussten: da hatte sich längst was eingenistet!\\n\\nEinige Schwangerschaftstests später – und Gott sei Dank durch das Ignorierens einer doch eher fragwürdigen Frauenärztin – war kurz vor dem Abflug nach Bali, um Sami und Jana auf ihrer Weltreise zu besuchen, klar: Da fliegt ein blinder Passagier mit. Still und leise hatte er sich eingenistet. Und wir groß war die Überraschung, als sich nach der Rückkehr herausstellte, dass es nicht nur bei einem geblieben ist.\\n\\nTja, Michi war schon immer sehr effizient: Ein Schuss – zwei Treffer. 😄\\n\\nIm September 2023 machten Marie & Lara die kleine Familie komplett. Mit ihnen wurde das Zuhause noch lebendiger, zwischendurch lauter, auf jeden Fall noch liebevoller, aber schnell wurde klar: die Wohnung in Obermais wurde für das wachsende Glück zu klein! Als in Terlan Hills sich die Gelegenheit bot, quasi ein ganzes Haus zu erwerben, wurde nicht lange gefackelt und so fand die junge Familie ein neues Daheim mit viel Platz und Raum für neue Geschichten.\\n\\nUnd hier beginnt das nächste Kapitel – und ihr seid alle mit dabei!\",\n        \"mainText\": \"\",\n        \"quote\": \"Für immer Zomm - Zomm - Zomm - Zomm....\",\n        \"backButtonText\": \"Zurück zur Startseite\",\n        \"fontSize\": {\n            \"title\": \"text-5xl\",\n            \"subtitle\": \"text-xl\",\n            \"introText\": \"text-lg\",\n            \"mainText\": \"text-base\",\n            \"quote\": \"text-lg\",\n            \"backButton\": \"text-lg\"\n        }\n    }\n};\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./app/lib/config.js\n");

